def _aggregate_experts_packed(
    self,
    state_dict: dict[str, Any],
    device_mesh: DeviceMesh | None,
) -> dict[str, Any]:
    """plan B:per-expert packed 字节(w1/w2/w3.weight int8 + .scale e8m0)直接重排
    stack 成 packed 参数布局,全程不反量化、不转置。

    产出键与 ``enable_packed_mxfp4_experts`` 注册的参数一致::

        model.layers.{L}.mlp.experts.gate_and_up_projs_packed  int8  [E, 2*inter, in//2]
        model.layers.{L}.mlp.experts.gate_and_up_projs_scale   uint8 [E, 2*inter, in//32]
        model.layers.{L}.mlp.experts.down_projs_packed         int8  [E, dim, inter//2]
        model.layers.{L}.mlp.experts.down_projs_scale          uint8 [E, dim, inter//32]

    布局即 ``pack_mxfp4(stacked_bf16.transpose(1, 2))`` 的结果(w1/w3 沿 out 维
    拼接、w2 原样),字节与 checkpoint 完全一致 —— pack/unpack 往返逐位无损
    (scripts/planb_probe.py),所以直通 stack 与「dequant 后再 pack」逐字节相同。
    不完整的层与 BF16 版一样静默留下,由加载后的 key diff 报告。
    """
    n_experts = self.moe_config.n_routed_experts

    if device_mesh is not None:
        start_expert, end_expert = get_expert_range_for_rank_from_mesh(device_mesh, n_experts)
        expected_per_rank = end_expert - start_expert
        rank = (
            get_submesh(device_mesh, ("ep",)).get_rank()
            if "ep" in device_mesh.mesh_dim_names
            else device_mesh.get_rank()
        )
    else:
        expected_per_rank = n_experts
        rank = None

    gu_w: dict[str, dict[int, dict[str, Any]]] = {}
    gu_s: dict[str, dict[int, dict[str, Any]]] = {}
    dn_w: dict[str, dict[int, Any]] = {}
    dn_s: dict[str, dict[int, Any]] = {}
    out: dict[str, Any] = {}

    for key in list(state_dict.keys()):
        value = state_dict.pop(key)
        m = _EXPERT_PATTERN.match(key) or _EXPERT_SCALE_PATTERN.match(key)
        if m is None:
            out[key] = value
            continue

        layer_num, expert_num, which = m.group(1), int(m.group(2)), m.group(3)

        if not should_load_expert_for_rank(expert_num, device_mesh, n_experts):
            continue

        if is_dtensor(value):
            value = value.to_local()

        if which in ("w1", "w3"):
            d = gu_s if key.endswith(".scale") else gu_w
            d.setdefault(layer_num, {}).setdefault(expert_num, {})[which] = value
        else:  # w2 = down_proj
            d = dn_s if key.endswith(".scale") else dn_w
            d.setdefault(layer_num, {})[expert_num] = value

    def _complete_gu(layer_num: str) -> bool:
        w_exp, s_exp = gu_w.get(layer_num, {}), gu_s.get(layer_num, {})
        return (
            len(w_exp) == expected_per_rank
            and len(s_exp) == expected_per_rank
            and all("w1" in d and "w3" in d for d in w_exp.values())
            and all("w1" in d and "w3" in d for d in s_exp.values())
        )

    for layer_num in set(gu_w) | set(gu_s):
        if not _complete_gu(layer_num):
            continue
        native_base = f"model.layers.{layer_num}.mlp.experts.gate_and_up_projs"
        ids = sorted(gu_w[layer_num])
        packed = torch.stack([torch.cat([gu_w[layer_num][e]["w1"], gu_w[layer_num][e]["w3"]], dim=0) for e in ids])
        scale = torch.stack([torch.cat([gu_s[layer_num][e]["w1"], gu_s[layer_num][e]["w3"]], dim=0) for e in ids])
        out[native_base + "_packed"] = create_dtensor_from_local(packed, device_mesh, rank)
        out[native_base + "_scale"] = create_dtensor_from_local(
            scale.view(torch.uint8), device_mesh, rank
        )

    for layer_num in set(dn_w) | set(dn_s):
        w_exp, s_exp = dn_w.get(layer_num, {}), dn_s.get(layer_num, {})
        if len(w_exp) != expected_per_rank or len(s_exp) != expected_per_rank:
            continue
        native_base = f"model.layers.{layer_num}.mlp.experts.down_projs"
        ids = sorted(w_exp)
        packed = torch.stack([w_exp[e] for e in ids])
        scale = torch.stack([s_exp[e] for e in ids])
        out[native_base + "_packed"] = create_dtensor_from_local(packed, device_mesh, rank)
        out[native_base + "_scale"] = create_dtensor_from_local(
            scale.view(torch.uint8), device_mesh, rank
        )

    return out

