def prepare_refit_info(self) -> Optional[dict[str, Any]]:
    """Prepare state dict metadata for weight refitting and IPC streaming."""
    state_dict_info = {}
    state_dict = self.model.state_dict()
    adapter = getattr(self.model, "state_dict_adapter", None)
    is_non_quantized = getattr(adapter, "_is_non_quantized", None)
    for name, tensor in state_dict.items():
        if name.endswith(".lora_A.weight") or name.endswith(".lora_B.weight"):
            continue
        # plan B:quantized refit 时 packed expert 条目走 _iter_packed_expert_refit,
        # 这里的元数据必须与它的产出逐键一致(vLLM 侧按本表查 shape/dtype 解析
        # 字节流;run24 的 KeyError 就是本表漏了 .scale 键)。
        if name.endswith("_scale") and name[: -len("_scale")] + "_packed" in state_dict:
            continue  # consumed together with the _packed entry
        if self.quantized_refit and name.endswith("_packed") and name[: -len("_packed")] + "_scale" in state_dict:
            for hf_key, shape, dtype in _packed_expert_refit_info(name, tuple(tensor.shape)):
                state_dict_info[hf_key] = (shape, dtype)
            continue
        full_tensor = (
            tensor.full_tensor() if isinstance(tensor, DTensor) else tensor
        )
        # all tensor will be casted to self.dtype in stream_weights_via_ipc_zmq/broadcast_weights_for_collective
        adapted_fqn_tensors = _maybe_adapt_tensor_to_hf(
            self.model, name, full_tensor
        )
        for adapted_fqn, adapted_tensor in adapted_fqn_tensors:
            if (
                self.quantized_refit
                and is_non_quantized is not None
                and adapted_fqn.endswith(".weight")
                and adapted_tensor.ndim >= 2
                and not is_non_quantized(adapted_fqn)
            ):
                # 与 pack_hf_refit_tensors 对齐:量化权重产出 fp8 weight +
                # 128x128 块 e8m0 scale 双键(expert 键在上面 packed 分支已处理)。
                base = adapted_fqn[: -len(".weight")]
                m, n = adapted_tensor.shape[-2], adapted_tensor.shape[-1]
                state_dict_info[adapted_fqn] = (adapted_tensor.shape, torch.float8_e4m3fn)
                state_dict_info[base + ".scale"] = (
                    ((m + 127) // 128, (n + 127) // 128),
                    torch.float8_e8m0fnu,
                )
            else:
                state_dict_info[adapted_fqn] = (adapted_tensor.shape, self.dtype)

    return state_dict_info

